# region: emit
def emit(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: gather
def gather(xs, limit=5):
    return [v if v <= limit else limit for v in xs]

# region: digest
def digest(xs, factor=10):
    return [v * factor for v in xs]

# region: sift
def sift(xs):
    return [v for v in xs if v % 2 == 0]

# region: render
def render(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs) - 1, 'tally': sorted(d.items())}

# region: intake
def intake(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(render(sift(digest(gather(emit(raw))))))

